using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Animation;

namespace Awl { partial class Shell {
 TextBlock captureQualityDetail;
 Color CaptureRecordColor(){return Color.FromRgb(214,90,80);}
 Brush CaptureRecordWash(){return new SolidColorBrush(Mix(baseColor,CaptureRecordColor(),.16));}
 Button CaptureBarIcon(string id,string tooltip,Action action,bool selected=false,bool record=false,double size=17){var brush=record?new SolidColorBrush(CaptureRecordColor()):selected?accentBrush:mutedBrush;var b=QuickButton(BuilderSvgIcon("capture-bar-"+id,size,brush),action,11,selected);b.Width=38;b.Height=38;b.Padding=new Thickness(0);b.Margin=new Thickness(0,0,3,0);b.BorderThickness=new Thickness(0);b.Background=record?CaptureRecordWash():selected?AccentWash(.16):Brushes.Transparent;b.Foreground=brush;b.ToolTip=tooltip;b.Focusable=false;ToolTipService.SetPlacement(b,System.Windows.Controls.Primitives.PlacementMode.Top);ToolTipService.SetInitialShowDelay(b,150);System.Windows.Automation.AutomationProperties.SetName(b,tooltip);return b;}
 Border CaptureBarDivider(){return new Border{Width=1,Height=22,Background=SoftBorder(),Margin=new Thickness(5,0,9,0),VerticalAlignment=VerticalAlignment.Center};}
 Border CaptureBarSurface(FrameworkElement child){return new Border{Background=SurfaceBrush(baseColor,1,false),BorderBrush=SoftBorder(),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(16),Padding=new Thickness(7),Child=child,Effect=ShellShadow()};}
 void SetCaptureBarContent(Window window,StackPanel row,string scaleName){row.Measure(new Size(Double.PositiveInfinity,Double.PositiveInfinity));var surface=window.Content as Border;if(surface!=null&&Object.ReferenceEquals(surface.Child,row)){double scale=SurfaceScale(scaleName);ApplySurfaceScale(surface,scaleName);window.Width=(row.DesiredSize.Width+16)*scale;window.Height=54*scale;}else SetCaptureContent(window,CaptureBarSurface(row),scaleName,row.DesiredSize.Width+16,54);PlaceCaptureWindow(window);}
 string CaptureLiveSize(long bytes){return bytes<1048576?(bytes/1024d).ToString("0.0")+" KB":(bytes/1048576d).ToString("0.0")+" MB";}
 StackPanel IdleCaptureBar(){var row=new StackPanel{Orientation=Orientation.Horizontal};row.Children.Add(CaptureBarIcon("region","Region",()=>{captureSource="Region";DrawCaptureStart(false);},captureSource=="Region"));row.Children.Add(CaptureBarIcon("window","Window",ShowCaptureWindowMenu,captureSource=="Window"));row.Children.Add(CaptureBarIcon("fullscreen","Full screen",()=>{captureSource="Full screen";DrawCaptureStart(false);},captureSource=="Full screen"));row.Children.Add(CaptureBarDivider());row.Children.Add(CaptureBarIcon("screenshot","Screenshot",()=>BeginCapture(false)));row.Children.Add(CaptureBarIcon("record","Record",()=>BeginCapture(true),false,true));row.Children.Add(CaptureBarDivider());Button history=null;history=CaptureBarIcon("last30","Save last 30 seconds",()=>ShowLast30Menu(history));row.Children.Add(history);row.Children.Add(CaptureBarDivider());var settings=CaptureBarIcon("settings","Capture settings",()=>DrawCaptureStart(true));settings.Margin=new Thickness(0);row.Children.Add(settings);return row;}
 FrameworkElement CaptureQualityContent(System.Drawing.Rectangle rect,string preset,long bytes){var values=PresetValues(preset,rect);var row=new StackPanel{Orientation=Orientation.Horizontal};string quality=preset.StartsWith("Native")?"Native":values.Item2>=2160?"4K":values.Item2+"p";var resolution=Text(quality,12,ink);resolution.FontWeight=FontWeights.Medium;row.Children.Add(resolution);var detail=Text("· "+(preset.StartsWith("Native")?"Native":preset)+" · "+CaptureLiveSize(bytes),12,mutedBrush);captureQualityDetail=detail;detail.Margin=new Thickness(8,0,8,0);row.Children.Add(detail);var arrow=BuilderSvgIcon("capture-bar-chev",11,mutedBrush);arrow.VerticalAlignment=VerticalAlignment.Center;row.Children.Add(arrow);return row;}
 void PaintCapturePause(Button button,bool paused){button.Content=BuilderSvgIcon("capture-bar-"+(paused?"play":"pause"),15,paused?mutedBrush:accentBrush);button.Background=paused?Brushes.Transparent:AccentWash(.16);button.ToolTip=paused?"Resume recording":"Pause recording";System.Windows.Automation.AutomationProperties.SetName(button,paused?"Resume recording":"Pause recording");}
 void PulseCaptureDot(FrameworkElement dot,bool running){dot.BeginAnimation(UIElement.OpacityProperty,null);dot.Opacity=running?1:.35;if(running)dot.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(1,.35,TimeSpan.FromMilliseconds(700)){AutoReverse=true,RepeatBehavior=RepeatBehavior.Forever});}
} }
